-- 📚 꼭집 주거 사전 — 금융정보 제공 동의 · 금융자산 조회 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.1초 · 결과:
-- {"anns": 85, "by_std": {"SH 고유": 1, "국민임대": 28, "매입임대": 24, "영구임대": 17, "전세임대": 3, "통합공공임대": 3, "행복주택": 6, "행복주택(신혼희망)": 3}, "txt": 99, "ex": ["SH_311349", "SH_310653", "SH_310650", "21390_부산광역시_사하구"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where '금융자산 조회'=cls),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='금융자산 조회' group by 1)q),'txt',(select count(distinct announcement_id) from y where t~'금융(정보|자산)[^.]{0,20}(조회|동의)'),'ex',(select json_agg(i) from(select distinct announcement_id i from y where '금융자산 조회'=cls order by 1 desc limit 4)q))j;
